    표8_상담적용: [
        {"상황":"죄책감에서 벗어나지 못하고 있는 성도", "성경원리":"바울은 '충분하다'고 선언했다. 그리스도 안에서 진정한 회개를 했다면, 더 이상 과도한 죄책감에 머물 필요가 없다.", "실제적용":"내담자가 충분히 회개했는지 확인하고, 충분히 회개했다면 '이제 충분하다, 이제 일어나라'고 선언적으로 권면한다. 요 8:11의 예수님의 말씀으로 격려한다"},
        {"상황":"용서해줬다고 했는데 계속 같은 잘못을 들먹이는 경우", "성경원리":"징계는 충분히 이루어진 후 끝나야 한다. 용서했다면 그 잘못을 계속 들먹이는 것은 진정한 용서가 아니다.", "실제적용":"용서의 의미를 구체적으로 탐구한다. 진정한 용서는 그 잘못을 더 이상 무기로 사용하지 않는 것임을 가르친다"},
        {"상황":"교회 징계를 어떻게 마무리해야 할지 모르는 리더", "성경원리":"징계의 목적이 달성되었을 때(회개와 변화) 공식적으로 종결을 선언해야 한다. 바울처럼 공동체 전체가 함께 결정하는 과정이 필요하다.", "실제적용":"징계 종결을 위한 구체적 기준(회개의 증거, 변화의 증거)을 미리 설정하고, 그 기준이 충족되었을 때 공식적으로 회복을 선언하는 의식을 갖는다"}
    ],
    표9_교차참조: [
        {"구절":"욥 42:10", "연결점":"욥의 고난이 끝나고 하나님이 회복시키신 것처럼, 충분한 징계 후에는 회복이 따른다", "구분":"구약"},
        {"구절":"시 51:1-2", "연결점":"다윗의 회개 시편 - 진정한 회개를 통해 징계에서 회복으로 나아가는 모범", "구분":"구약"},
        {"구절":"렘 31:34", "연결점":"내가 저희 죄악을 사하고 다시는 저희 죄를 기억지 아니하리라 - 완전한 용서의 약속", "구분":"구약"},
        {"구절":"미 7:18", "연결점":"주와 같은 신이 어디 있으리이까 주께서는 죄악을 사유하시며 허물을 넘기시며 - 과도하지 않고 충분한 용서를 베푸시는 하나님", "구분":"구약"},
        {"구절":"눅 15:20-24", "연결점":"탕자가 돌아왔을 때 아버지의 완전한 용서와 회복 - 징계 후 회복의 완전한 모범", "구분":"신약"},
        {"구절":"요 8:11", "연결점":"나도 너를 정죄하지 아니하노니 가서 다시는 죄를 범치 말라 - 충분한 징계 후 새 시작을 허용하는 예수님의 은혜", "구분":"신약"},
        {"구절":"갈 6:1", "연결점":"신령한 너희는 온유한 심령으로 그러한 자를 바로잡고 - 회복을 목표로 하는 교회 훈련", "구분":"신약"},
        {"구절":"살후 3:14-15", "연결점":"그를 원수와 같이 생각지 말고 형제같이 권하라 - 징계 중에도 형제로 여기며 회복을 목표로 해야 한다", "구분":"신약"}
    ]
